import { Card, CardBody, CardTitle, Container, Row, Col } from "reactstrap";
import { useEffect, useState } from "react";
import { db } from "../../firebase"; 
import { collection, getDocs, doc, getDoc } from "firebase/firestore";

const Header = () => {
  const [carbonData, setCarbonData] = useState({
    footprint: 0,
    credits: 0,
    progress: 0,
    rank: "Loading..."
  });

  const [previousData, setPreviousData] = useState({
    footprint: 0,
    credits: 0,
    progress: 0,
  });

  useEffect(() => {
    const fetchAverageCarbonData = async () => {
      try {
        const querySnapshot = await getDocs(collection(db, "carbonFootprint"));
        const data = querySnapshot.docs.map(doc => doc.data());

        if (data.length === 0) return;

        // Fetch previous averages
        const previousDocRef = doc(db, "carbonFootprint", "previousData");
        const previousDocSnap = await getDoc(previousDocRef);

        if (previousDocSnap.exists()) {
          setPreviousData(previousDocSnap.data());
        }

        // Calculate Averages
        const totalEntries = data.length;
        const avgFootprint = data.reduce((sum, d) => sum + parseFloat(d.totalCarbon || 0), 0) / totalEntries;
        const avgCredits = data.reduce((sum, d) => sum + parseFloat(d.credits || 0), 0) / totalEntries;
        const avgProgress = data.reduce((sum, d) => sum + parseFloat(d.progress || 0), 0) / totalEntries;

        // Determine Rank
        const rank = getRank(avgFootprint, avgCredits);

        setCarbonData({
          footprint: avgFootprint.toFixed(2),
          credits: avgCredits.toFixed(2),
          progress: avgProgress.toFixed(2),
          rank
        });

      } catch (error) {
        console.error("Error fetching data:", error);
      }
    };

    fetchAverageCarbonData();
  }, []);

  // Function to calculate percentage change
  const getTrend = (current, previous) => {
    if (previous === 0) return { icon: "fas fa-minus", color: "muted", change: "0%" };

    const change = (((current - previous) / previous) * 100).toFixed(2);
    if (current > previous) {
      return { icon: "fas fa-arrow-up", color: "danger", change: `+${change}%` };
    } else if (current < previous) {
      return { icon: "fas fa-arrow-down", color: "success", change: `${change}%` };
    } else {
      return { icon: "fas fa-minus", color: "muted", change: "0%" };
    }
  };

  // Function to determine rank
  const getRank = (footprint, credits) => {
    if (footprint <= 100 && credits >= 500) return "🌍 Eco Warrior";
    if (footprint <= 300 && credits >= 300) return "🍃 Green Guardian";
    if (footprint <= 600 && credits >= 150) return "🌱 Sustainable Citizen";
    if (footprint <= 900 && credits >= 50) return "⚡ Conscious Consumer";
    if (footprint <= 1500 && credits < 50) return "🔥 Carbon Heavyweight";
    return "🚨 Polluter";
  };

  return (
    <div className="header bg-gradient-info pb-8 pt-5 pt-md-8">
      <Container fluid>
        <div className="header-body">
          <Row>
            {/* Carbon Footprint */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Avg Carbon Footprint (kg CO₂)
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.footprint}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-danger text-white rounded-circle shadow">
                        <i className="fas fa-chart-bar" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${getTrend(carbonData.footprint, previousData.footprint).color} mr-2`}>
                      <i className={getTrend(carbonData.footprint, previousData.footprint).icon} /> 
                      {getTrend(carbonData.footprint, previousData.footprint).change}
                    </span>{" "}
                    <span className="text-nowrap">Since last time</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            {/* Carbon Credits Earned */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Avg Carbon Credits
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.credits}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-warning text-white rounded-circle shadow">
                        <i className="fas fa-chart-pie" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${getTrend(carbonData.credits, previousData.credits).color} mr-2`}>
                      <i className={getTrend(carbonData.credits, previousData.credits).icon} /> 
                      {getTrend(carbonData.credits, previousData.credits).change}
                    </span>{" "}
                    <span className="text-nowrap">Since last time</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            {/* Carbon Reduction Progress */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Avg Carbon Progress (%)
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.progress}</span>
                    </div>
                    <Col className="col-auto">
                      <div className="icon icon-shape bg-info text-white rounded-circle shadow">
                        <i className="fas fa-users" />
                      </div>
                    </Col>
                  </Row>
                  <p className="mt-3 mb-0 text-muted text-sm">
                    <span className={`text-${getTrend(carbonData.progress, previousData.progress).color} mr-2`}>
                      <i className={getTrend(carbonData.progress, previousData.progress).icon} /> 
                      {getTrend(carbonData.progress, previousData.progress).change}
                    </span>{" "}
                    <span className="text-nowrap">Since last time</span>
                  </p>
                </CardBody>
              </Card>
            </Col>

            {/* Rank */}
            <Col lg="6" xl="3">
              <Card className="card-stats mb-4 mb-xl-0">
                <CardBody>
                  <Row>
                    <div className="col">
                      <CardTitle tag="h5" className="text-uppercase text-muted mb-0">
                        Rank
                      </CardTitle>
                      <span className="h2 font-weight-bold mb-0">{carbonData.rank}</span>
                    </div>
                  </Row>
                </CardBody>
              </Card>
            </Col>
          </Row>
        </div>
      </Container>
    </div>
  );
};

export default Header;
